from batch07 import *
start('automation','Automatyzacja — JSON i API','6.5',['https://developer.cisco.com/docs/hyperfabric/getting-started/','https://www.cisco.com/c/en/us/td/docs/security/asa/api/asa_rest_api.html','https://developer.cisco.com/docs/intersight/supported-http-methods/'])
q('API zamiast klikania','Co daje programistyczny interfejs API do zarządzania siecią?','Powtarzalne operacje na udokumentowanych zasobach',['Gwarancję braku błędów konfiguracji|Automatyzacja może także powielać błędy.','Brak konieczności uwierzytelniania|API nadal wymaga kontroli dostępu.','Zawsze brak wpływu na urządzenia|Operacje zapisu mogą zmieniać ich stan.'],'API umożliwia automatyzację, ale wymaga walidacji wejścia i oceny skutków.')
q('Odczyt zasobu','Która metoda HTTP typowo służy do odczytu zasobu REST bez intencji zmiany jego stanu?','GET',['DELETE|DELETE służy do usuwania zasobu.','PUT|PUT jest metodą zapisu reprezentacji zasobu.','PATCH|PATCH służy do częściowej modyfikacji.'],'GET jest metodą odczytu; dokładny kontrakt konkretnego API nadal trzeba sprawdzić.')
q('Nowy zasób','Dokumentacja API opisuje utworzenie nowego obiektu przez POST /interfaces. Której metody użyjesz?','POST',['GET|Kontrakt wskazuje POST, a GET służy do odczytu.','DELETE|Usuwa zamiast tworzyć zgodnie z opisanym kontraktem.','TRACE|Nie jest opisaną metodą tworzenia zasobu.'],'Metodę i ścieżkę wybiera się z dokumentacji danego API, nie z samego podobieństwa nazw.')
q('Obiekt JSON','Który zapis jest poprawnym obiektem JSON?','{"enabled": true}',['{enabled: true}|W JSON nazwa klucza wymaga podwójnych cudzysłowów.',"{'enabled': true}|JSON nie używa pojedynczych cudzysłowów do stringów.",'{"enabled": yes}|JSON używa true lub false; yes nie jest literałem logicznym JSON.'],'JSON ma ścisłą składnię: klucze są stringami w podwójnych cudzysłowach.')
q('Tablica JSON','Jakiego typu jest wartość interfaces w {"interfaces": ["Gi0/0", "Gi0/1"]}?','Tablica',['Liczba całkowita|Wartość zawiera listę elementów w nawiasach kwadratowych.','Pojedynczy string|Cała wartość nie jest jednym napisem.','Wartość null|Lista zawiera dwa elementy, nie null.'],'Nawiasy kwadratowe oznaczają tablicę; kolejność jej elementów ma znaczenie.')
q('Typ logiczny a tekst','Czy JSON true oraz "true" mają ten sam typ?','Nie: boolean i string',['Tak, cudzysłowy są zawsze ignorowane|Cudzysłowy definiują typ tekstowy.','Tak, oba są liczbami|Żaden nie jest zapisem liczby.','Nie, true jest błędną składnią|true jest poprawnym literałem JSON.'],'Poprawny typ danych jest częścią kontraktu API, nie tylko estetyką zapisu.')
q('Usunięcie obiektu','API dokumentuje usuwanie VLAN-u metodą DELETE /vlans/50. Jaki skutek należy ocenić przed wysłaniem?','Wpływ usunięcia VLAN-u na usługi korzystające z niego',['Wyłącznie kolor przycisku aplikacji|Nie opisuje zależności sieciowych.','Tylko zmianę nazwy pliku lokalnego|To operacja zdalna na zasobie.','Żaden, DELETE zawsze jest odczytem|DELETE jest operacją usuwania.'],'Automatyzacja nie znosi konieczności analizy zależności i uprawnień.')
q('Częściowa aktualizacja','Dokumentacja mówi, że PATCH zmienia tylko przesłane właściwości. Chcesz zmienić opis portu. Co wyślesz?','PATCH z polem opisu zgodnym ze schematem',['DELETE całego portu|To usuwa zasób zamiast zmienić opis.','GET z opisem w nazwie hosta|Nie realizuje opisanego kontraktu aktualizacji.','Losowy pełny obiekt z brakującymi wartościami|Może nadpisać niezamierzone ustawienia.'],'Częściowa aktualizacja wymaga znajomości semantyki PATCH i właściwego Content-Type.')
q('Idempotencja','Co znaczy, że operacja jest idempotentna?','Powtórzenie tego samego żądania ma taki sam zamierzony efekt stanu jak jedno wykonanie',['Każda odpowiedź musi mieć identyczny kod HTTP|Stan efektu i treść odpowiedzi to różne rzeczy.','Operacja nigdy niczego nie zmienia|Idempotentny zapis może zmieniać stan.','Operacja zawsze kończy się bez błędu|Idempotencja nie jest gwarancją powodzenia.'],'Powtarzalność efektu ułatwia bezpieczne ponawianie, ale musi wynikać z kontraktu operacji.')
q('401 z API','Żądanie zwraca 401 Unauthorized. Co sprawdzisz najpierw?','Obecność i ważność wymaganych danych uwierzytelnienia',['Od razu wszystkie VLAN-y na przełączniku|Nie odpowiada znaczeniu błędu uwierzytelnienia.','Zmianę subnet mask każdego hosta|Nie jest pierwszym krokiem przy 401.','Czy JSON ma większą czcionkę|Format wizualny nie uwierzytelnia żądania.'],'401 wskazuje problem z uwierzytelnieniem; nie należy od razu zmieniać konfiguracji ruchowej.')
q('403 z API','Token został rozpoznany, lecz API zwraca 403 Forbidden przy zapisie. Co sprawdzić?','Uprawnienia i politykę dostępu do operacji',['Automatycznie powtarzać w nieskończoność|Brak uprawnień zwykle nie znika od liczby prób.','Wyłączyć wszystkie ACL bez analizy|To nieuzasadniona reakcja.','Zamienić HTTP na ARP|ARP nie wykonuje operacji REST.'],'Uwierzytelniona tożsamość nie musi mieć prawa do każdej operacji.')
q('200 a zgodność stanu','GET zwrócił 200 i listę portów. Czy sam kod 200 potwierdza zgodność konfiguracji z projektem?','Nie, trzeba sprawdzić treść odpowiedzi',['Tak, 200 oznacza pełną zgodność projektu|Kod informuje o powodzeniu żądania, nie o intencji projektu.','Tak, GET automatycznie naprawia konfigurację|GET nie jest metodą naprawy stanu.','Nie, bo 200 zawsze oznacza błąd|200 jest kodem powodzenia.'],'Stan odczytany z API trzeba porównać z oczekiwanymi warunkami.')
q('Utracona odpowiedź POST','Po wysłaniu operacji tworzenia zasobu nastąpił timeout. Nie wiadomo, czy zapis zaszedł. Co jest rozsądne?','Sprawdzić stan lub udokumentowaną idempotencję przed ponowieniem',['Zakładać, że timeout zawsze oznacza brak zapisu|Zapis mógł zajść przed utratą odpowiedzi.','Wysyłać POST bez limitu|Może to tworzyć duplikaty lub przeciążać usługę.','Usunąć wszystkie podobne zasoby|To nie jest bezpieczne ustalenie wyniku operacji.'],'Timeout odpowiedzi nie przesądza o wyniku zmiany po stronie serwera.')
q('Paginacja','API zwraca 100 obiektów i next link, ale sieć ma więcej urządzeń. Jak zebrać pełny wynik?','Przechodzić po kolejnych stronach zgodnie z kontraktem',['Uznać pierwsze 100 za całą sieć|Obecność kolejnej strony przeczy kompletności.','Dopisać brakujące urządzenia losowo|To fałszowałoby inwentarz.','Zmienić typ JSON na obraz|Nie rozwiązuje paginacji.'],'Automatyzacja musi uwzględniać paginację, aby nie podejmować decyzji na niepełnym inwentarzu.')
q('Asynchroniczne zadanie','API przyjęło zmianę i zwróciło identyfikator zadania ze statusem pending. Co dalej?','Sprawdzić zakończenie zadania i stan docelowy',['Ogłosić natychmiast pełne powodzenie|Przyjęcie nie oznacza zakończenia.','Ponownie tworzyć zadanie co sekundę|Powiela operacje zamiast śledzić istniejącą.','Ignorować identyfikator zadania|Traci się sposób sprawdzenia jego wyniku.'],'Przyjęcie żądania, wykonanie operacji i weryfikacja efektu to oddzielne etapy.')
q('Sekret w repozytorium','Gdzie umieścić token API używany przez skrypt zespołu?','W kontrolowanym mechanizmie sekretów, pobieranym podczas uruchomienia',['W publicznym kodzie źródłowym|To ujawnia dane dostępowe.','W nazwie każdego pliku logu|Nazwy plików często są widoczne szerzej.','W komentarzu przy adresie URL|Komentarz w repozytorium nie jest ochroną sekretu.'],'Token powinien mieć ograniczone uprawnienia i być chroniony przed ujawnieniem w kodzie oraz logach.')
q('Walidacja schematu','API wymaga mtu jako liczby, a skrypt wysyła "1500" jako tekst. Co poprawić?','Wysłać wartość liczbową zgodną ze schematem',['Zostawić tekst, typy nie mają znaczenia|API może rygorystycznie walidować typy.','Usunąć uwierzytelnianie|Nie rozwiązuje typu danych.','Przestawić port w shutdown|Nie naprawia struktury JSON.'],'Zgodność składni JSON nie wystarcza: potrzebna jest także zgodność typów i zakresów kontraktu.')
q('Najpierw mała grupa','Masz skrypt zmiany opisu na 500 portach. Co najlepiej ogranicza ryzyko pomyłki w selektorze?','Podgląd różnic i wykonanie na małej zweryfikowanej grupie przed resztą',['Od razu równoległy zapis wszędzie|Powiększa zasięg pomyłki przed jej wykryciem.','Usunięcie logowania błędów|Utrudnia kontrolę efektów.','Losowy wybór identyfikatorów|Nie zapewnia zgodności z zamiarem.'],'Automatyzację wdraża się z walidacją zakresu, kontrolą wyników i możliwością wycofania zmian.')
end()
